// Commandes de supervision. Liste BLANCHE : seuls ces workflows peuvent être mis en pause.
// Le bot et l'alerte panne n'y figurent pas : on ne peut pas se couper soi-même l'accès.
const PILOTABLES = { veille: 'veilleCyber00001', rapport: 'rapportQuotidien', podcast: 'podcastMatin0001' };
const e = $input.first().json;
const commande = e.commande ?? 'statut';
const argument = String(e.argument ?? '').toLowerCase();

if (commande === 'pause' || commande === 'reprendre') {
  const id = PILOTABLES[argument];
  if (!id) return [{ json: { sortie: 3, texte: `Usage : /${commande} veille | rapport | podcast` } }];
  return [{ json: { sortie: 2, id, nom: argument, action: commande === 'pause' ? 'deactivate' : 'activate' } }];
}
// Appels internes du bot : « contexte » = statut + historique 24 h, « rien » = rien à fournir
if (commande === 'rien') return [{ json: { sortie: 3, texte: '' } }];
return [{ json: { sortie: commande === 'erreurs' ? 1 : 0, contexte: commande === 'contexte' } }];

// Contrôle de santé des conteneurs (réponse attendue en moins de 5 s)
const SERVICES = {
  cerveau: 'http://cerveau:8080/sante',
  voix: 'http://voix:8080/sante',
  studio: 'http://studio:8080/sante',
  relais: 'http://relais-telegram:8081/sante',
};
const etat = {};
for (const [nom, url] of Object.entries(SERVICES)) {
  try {
    await this.helpers.httpRequest({ url, timeout: 5000 });
    etat[nom] = true;
  } catch {
    etat[nom] = false;
  }
}
return [{ json: { conteneurs: etat } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lire = nom => { try { return $(nom).first().json; } catch { return {}; } };
const heure = d => d ? DateTime.fromISO(d).setZone('Europe/Paris').toFormat("dd/MM HH'h'mm") : '—';

const conteneurs = lire('Santé des conteneurs').conteneurs ?? {};
const wfs = lire('Lister les workflows');
const exs = lire('Dernières exécutions');

const L = [`🩺 <b>Statut</b> — ${$now.setZone('Europe/Paris').toFormat("dd/MM HH'h'mm")}`, '', '<b>Conteneurs</b>'];
L.push(Object.entries(conteneurs).map(([n, ok]) => `${ok ? '✅' : '❌'} ${n}`).join(' · ') + ' · ✅ n8n');

L.push('', '<b>Workflows</b>');
if (wfs.error) L.push('⚠️ API n8n injoignable : ' + esc(String(wfs.error.message ?? '').slice(0, 100)));
// Les tests manuels (bouton « Execute ») ne sont pas des pannes : on les ignore
const executions = (exs.data ?? []).filter(e => e.mode !== 'manual');
const ilYa24h = Date.now() - 24 * 3600 * 1000;
for (const w of (wfs.data ?? []).filter(w => !w.name.startsWith('TEST')).sort((a, b) => a.name.localeCompare(b.name))) {
  const ex = executions.filter(e => e.workflowId === w.id);
  const derniere = ex[0];
  const echecs = ex.filter(e => e.status === 'error' && new Date(e.startedAt).getTime() > ilYa24h).length;
  const icone = !w.active ? '⏸️' : echecs ? '⚠️' : '✅';
  const statutDerniere = derniere ? `${derniere.status === 'success' ? '✓' : derniere.status === 'error' ? '✗' : '…'} ${heure(derniere.startedAt)}` : 'aucune';
  L.push(`${icone} ${esc(w.name)}${w.active ? '' : ' <i>(en pause)</i>'} — dernière : ${statutDerniere}${echecs ? ` — <b>${echecs} échec(s) en 24 h</b>` : ''}`);
}

const total = executions.filter(e => e.status === 'error' && new Date(e.startedAt).getTime() > ilYa24h).length;
L.push('', total ? `⚠️ <b>${total} erreur(s) en 24 h</b> : détails avec /erreurs` : '👌 Aucune erreur en 24 h');
// Pour le bot : historique des dernières 24 h (une exécution n'implique pas forcément un envoi)
if ($('Comprendre la commande').first().json.contexte) {
  L.push('', 'Historique des exécutions automatiques (24 h) :');
  const noms = Object.fromEntries((wfs.data ?? []).map(w => [w.id, w.name]));
  for (const e of executions.filter(e => new Date(e.startedAt).getTime() > ilYa24h && e.mode === 'trigger').slice(0, 40))
    L.push(`- ${heure(e.startedAt)} ${noms[e.workflowId] ?? e.workflowId} : ${e.status}`);
}
return [{ json: { texte: L.join('\n') } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r = $input.first().json;
if (r.error) return [{ json: { texte: '⚠️ API n8n injoignable : ' + esc(String(r.error.message ?? '').slice(0, 100)) } }];
const noms = {};
try { for (const w of $('Noms des workflows').first().json.data ?? []) noms[w.id] = w.name; } catch {}
// Les tests manuels ne sont pas des pannes : on les ignore
const liste = (r.data ?? []).filter(e => e.mode !== 'manual').slice(0, 5);
if (!liste.length) return [{ json: { texte: '👌 Aucune erreur récente.' } }];
const L = ['🚨 <b>Dernières erreurs</b>'];
for (const e of liste) {
  const res = e.data?.resultData ?? {};
  const msg = res.error?.message ?? res.error?.description ?? 'erreur inconnue';
  L.push('', `<b>${esc(noms[e.workflowId] ?? e.workflowId)}</b> — ${DateTime.fromISO(e.startedAt).setZone('Europe/Paris').toFormat("dd/MM HH'h'mm")}`,
         `Bloc : ${esc(res.lastNodeExecuted ?? '?')}`, `<i>${esc(String(msg).slice(0, 200))}</i>`);
}
return [{ json: { texte: L.join('\n') } }];

const r = $input.first().json;
const { nom, action } = $('Comprendre la commande').first().json;
if (r.error) return [{ json: { texte: `⚠️ Impossible de modifier « ${nom} » : ${String(r.error.message ?? '').slice(0, 150)}` } }];
return [{ json: { texte: action === 'deactivate'
  ? `⏸️ <b>${nom}</b> est en pause. Reprends-le avec /reprendre ${nom}`
  : `▶️ <b>${nom}</b> est de nouveau actif.` } }];
